p=Path('work/vulkan_graphics_pipeline_candidate.h');s=p.read_text();s=s.replace('VkPipeline pipeline=VK_NULL_HANDLE;','VkPipeline pipeline=VK_NULL_HANDLE,translucentPipeline=VK_NULL_HANDLE;');s=s.replace('auto cleanup=[&](){','auto cleanup=[&](){if(translucentPipeline)destroyPipeline(dev,translucentPipeline,nullptr);');needle='check(createPipeline(dev,VK_NULL_HANDLE,1,&pipelineInfo,nullptr,&pipeline));';assert needle in s;s=s.replace(needle,needle+'depthState.depthWriteEnable=VK_FALSE;blend.blendEnable=VK_TRUE;blend.srcColorBlendFactor=VK_BLEND_FACTOR_SRC_ALPHA;blend.dstColorBlendFactor=VK_BLEND_FACTOR_ONE_MINUS_SRC_ALPHA;blend.colorBlendOp=VK_BLEND_OP_ADD;blend.srcAlphaBlendFactor=VK_BLEND_FACTOR_ONE;blend.dstAlphaBlendFactor=VK_BLEND_FACTOR_ONE_MINUS_SRC_ALPHA;blend.alphaBlendOp=VK_BLEND_OP_ADD;check(createPipeline(dev,VK_NULL_HANDLE,1,&pipelineInfo,nullptr,&translucentPipeline));');s=s.replace('pass,pipeline,layout,setLayout,base);','pass,pipeline,translucentPipeline,layout,setLayout,base);');p.write_text(s)
